<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref } from 'vue';
import { useRoute, useRouter, onBeforeRouteLeave } from 'vue-router';
import { api, errorText, mutationId, session } from '../api';
import { clone, modeLabels, nextDate, type JourneyList, type JourneySummary, type RouteDay, type RouteStop, type TravelMode, type RouteSnapshot, type PlaceInput } from '../../../packages/contracts/src/index.js';
import { useJourneyWorkspace } from '../useJourneyWorkspace';
import { loadAtlasCatalog } from '../atlasCatalog';
import type { PlaceResult } from '../maps/placeSearch';
import AtlasIcon from '../components/AtlasIcon.vue';
import ModalSheet from '../components/ModalSheet.vue';
import JourneyMap from '../components/JourneyMap.vue';
import JourneyPlaceSearch from '../components/JourneyPlaceSearch.vue';
import '../styles/journey-workspace.css';
const page=useRoute(),router=useRouter(),work=useJourneyWorkspace();
const {data,loading,error,saving,state,arrivalModes,scheduled,allPoints}=work;
const journeyId=typeof page.params.id==='string'?page.params.id:'', filter=ref<JourneySummary['status']>('planning'),items=ref<JourneySummary[]>([]),cursor=ref<string|null>(null),listBusy=ref(false),listError=ref('');
type Sheet='create'|'more'|'rename'|'dates'|'point'|'move'|'group'|'deleteDay'|'transport'|'record'|'delete'|'listMore'|null;
const modal=ref<Sheet>(null),modalError=ref(''),modalBusy=ref(false),input=ref(''),cityChoice=ref(''),cities=ref<{code:string;name:string}[]>([]),dateInput=ref(''),nameDraft=ref(''),statusNotice=ref('');let noticeTimer:ReturnType<typeof setTimeout>|undefined;const wideScreen=window.matchMedia('(min-width: 1024px)'),desktop=ref(wideScreen.matches),mapSeen=ref(false);const resizeScreen=()=>desktop.value=wideScreen.matches;wideScreen.addEventListener('change',resizeScreen);
const groupId=ref(''),view=ref<'list'|'map'>('list'),selectedPoint=ref<string|null>(null),batch=ref(false),selected=ref<string[]>([]),pointsScroll=ref<HTMLElement>(),scrolls=new Map<string,number>();
const search=ref(false),searchTarget=ref(''),searchRecord=ref(false),locating=ref<string|null>(null),recordExtras=ref<(RouteStop&{place?:PlaceInput;poiId?:string})[]>([]),recordSelected=ref<string[]>([]),recordDate=ref('');
const detail=ref({time:'',note:'',stay:''}),transportTarget=ref<string|null>(null),createKey=mutationId();let recordKey=mutationId(),deleteKey=mutationId(),listGeneration=0;
const group=computed(()=>data.value?.route.days.find(d=>d.id===groupId.value)||data.value?.route.days[0]),pending=computed(()=>data.value?.route.days.find(d=>d.unscheduled));
const groupName=(day?:RouteDay)=>!day||day.unscheduled?'待安排':'第 '+(scheduled.value.findIndex(d=>d.id===day.id)+1)+' 天';
const active=computed(()=>allPoints.value.find(p=>p.id===selectedPoint.value));
const undoItems=ref<{dayId:string;index:number;point:RouteStop;place?:PlaceInput;poiId?:string;stay?:string;mode?:TravelMode}[]>([]);
const addedIds=computed(()=>searchRecord.value?recordExtras.value.map(p=>p.poiId||p.id):(data.value?.route.days.find(d=>d.id===searchTarget.value)?.stops||[]).map(p=>data.value?.preferences.poiIds[p.id]||''));
const searchCount=computed(()=>searchRecord.value?recordExtras.value.length:data.value?.route.days.find(d=>d.id===searchTarget.value)?.stops.length||0);
const searchCity=computed(()=>data.value?.journey.destinations[0]||'');
const recordPoints=computed(()=>[...allPoints.value,...recordExtras.value]);
const confirmed=computed(()=>data.value?.confirmedSourceIds||[]);
const contextKey='atlas-workspace-view:'+session.value?.user.id+':'+journeyId;
async function loadList(more=false){const generation=++listGeneration;listBusy.value=true;listError.value='';try{const params=new URLSearchParams({status:filter.value});if(more&&cursor.value)params.set('cursor',cursor.value);const r=await api<JourneyList>('/journeys?'+params);if(generation===listGeneration){items.value=more?[...items.value,...r.items]:r.items;cursor.value=r.nextCursor;}}catch(e){listError.value=errorText(e);}finally{if(generation===listGeneration)listBusy.value=false;}}
function setFilter(value:JourneySummary['status']){filter.value=value;items.value=[];cursor.value=null;void loadList();}
function notify(text:string){statusNotice.value=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>statusNotice.value='',2500);}
function remember(){if(pointsScroll.value)scrolls.set(groupId.value,pointsScroll.value.scrollTop);try{sessionStorage.setItem(contextKey,JSON.stringify({group:groupId.value,view:view.value,active:selectedPoint.value,scrolls:[...scrolls]}));}catch{}}
async function changeGroup(id:string){remember();groupId.value=id;selectedPoint.value=null;statusNotice.value='';await nextTick();if(pointsScroll.value)pointsScroll.value.scrollTop=scrolls.get(id)||0;remember();}
async function setView(value:'list'|'map'){remember();view.value=value;if(value==='map')mapSeen.value=true;statusNotice.value='';await nextTick();if(pointsScroll.value)pointsScroll.value.scrollTop=scrolls.get(groupId.value)||0;remember();}
function open(sheet:Sheet){modalError.value='';modal.value=sheet;}
function newJourney(){input.value=typeof page.query.title==='string'?page.query.title:typeof page.query.destination==='string'?page.query.destination:'';cityChoice.value=typeof page.query.destination==='string'?page.query.destination:'';open('create');}
async function create(){if(modalBusy.value)return;modalBusy.value=true;modalError.value='';try{const r=await api<{id:string}>('/workspace/journeys','POST',{title:input.value.trim(),destination:cityChoice.value,clientMutationId:createKey});modal.value=null;await router.replace('/journeys/'+r.id);}catch(e){modalError.value=errorText(e);}finally{modalBusy.value=false;}}
function addDay(){if(scheduled.value.length>=30){notify('每次旅程最多安排 30 天');return;}const id=mutationId(),start=scheduled.value[0]?.date||null;work.change(()=>data.value!.route.days.push({id,title:'第 '+(scheduled.value.length+1)+' 天',area:'',date:nextDate(start,scheduled.value.length),stayName:'',stops:[]}));void changeGroup(id);}
function openSearch(record=false,pointId:string|null=null){searchRecord.value=record;searchTarget.value=group.value!.id;locating.value=pointId;modal.value=null;search.value=true;}
function plainPoint(place:PlaceResult):RouteStop{return{id:mutationId(),label:place.name.slice(0,160),region:[place.city,place.address].filter(Boolean).join(' · ').slice(0,120),time:null,note:'',role:'visit',location:place.location};}
function usePlace(place:PlaceResult,update=false){
 if(searchRecord.value){const p=recordExtras.value.find(p=>p.poiId===place.id);if(p){if(update){p.location=place.location;p.place=place.place;}else{recordExtras.value=recordExtras.value.filter(x=>x!==p);recordSelected.value=recordSelected.value.filter(id=>id!==p.id);}}else{const point={...plainPoint(place),place:place.place,poiId:place.id};recordExtras.value.push(point);recordSelected.value.push(point.id);}return;}
 const d=data.value!,target=d.route.days.find(g=>g.id===searchTarget.value)!;
 if(locating.value){const p=allPoints.value.find(p=>p.id===locating.value);if(p)work.change(()=>{p.location=place.location;if(place.place)d.preferences.places[p.id]=place.place!;});search.value=false;showPoint(locating.value);return;}
 const existing=target.stops.find(p=>d.preferences.poiIds[p.id]===place.id);
 if(existing){if(update)work.change(()=>{existing.location=place.location;});else removePoints([existing.id]);return;}
 if(allPoints.value.length>=200){notify('每次旅程最多添加 200 个地点');return;}
 const point=plainPoint(place);work.change(()=>{target.stops.push(point);d.preferences.poiIds[point.id]=place.id;if(place.place)d.preferences.places[point.id]=place.place;if(place.city&&!d.journey.destinations.includes(place.city)&&d.journey.destinations.length<30)d.journey.destinations.push(place.city);const mode=d.preferences.defaultModes[target.id];if(mode)arrivalModes.value[point.id]=mode;});
}
function showPoint(id:string){selectedPoint.value=id;const p=active.value;if(!p)return;detail.value={time:p.time||'',note:p.note,stay:data.value!.preferences.stayNotes[id]||''};open('point');}
function savePoint(close=true){const p=active.value;if(!p)return;work.change(()=>{p.time=detail.value.time||null;p.note=detail.value.note;data.value!.preferences.stayNotes[p.id]=detail.value.stay;});if(close)modal.value=null;}
function toggleSelected(id:string){selected.value=selected.value.includes(id)?selected.value.filter(p=>p!==id):[...selected.value,id];}
function selectAll(){const ids=group.value!.stops.map(p=>p.id),all=ids.every(id=>selected.value.includes(id));selected.value=all?selected.value.filter(id=>!ids.includes(id)):[...new Set([...selected.value,...ids])];}
function moveTo(targetId:string){const ids=new Set(selected.value),d=data.value!,target=d.route.days.find(g=>g.id===targetId)!;const moved=d.route.days.flatMap(g=>g.id===targetId?[]:g.stops.filter(p=>ids.has(p.id)));
 work.change(()=>{for(const g of d.route.days)if(g.id!==targetId)g.stops=g.stops.filter(p=>!ids.has(p.id));target.stops.push(...moved);});batch.value=false;selected.value=[];modal.value=null;void changeGroup(targetId);notify('已移到'+groupName(target));}
function removePoints(ids:string[]){const set=new Set(ids),d=data.value!;undoItems.value=d.route.days.flatMap(g=>g.stops.flatMap((p,index)=>set.has(p.id)?[{dayId:g.id,index,point:clone(p),place:d.preferences.places[p.id]?clone(d.preferences.places[p.id]):undefined,poiId:d.preferences.poiIds[p.id],stay:d.preferences.stayNotes[p.id],mode:arrivalModes.value[p.id]}]:[]));
 work.change(()=>{for(const g of d.route.days)g.stops=g.stops.filter(p=>!set.has(p.id));});selected.value=[];batch.value=false;if(!search.value)modal.value=null;selectedPoint.value=null;}
function undo(){const d=data.value!;work.change(()=>{for(const item of undoItems.value){const target=d.route.days.find(g=>g.id===item.dayId)||pending.value!;if(!allPoints.value.some(p=>p.id===item.point.id))target.stops.splice(Math.min(item.index,target.stops.length),0,item.point);if(item.place)d.preferences.places[item.point.id]=item.place;if(item.poiId)d.preferences.poiIds[item.point.id]=item.poiId;if(item.stay)d.preferences.stayNotes[item.point.id]=item.stay;if(item.mode)arrivalModes.value[item.point.id]=item.mode;}});undoItems.value=[];notify('已恢复移除的地点');}
function deleteDay(keep:boolean){const current=group.value!;if(current.unscheduled)return;if(!keep)removePoints(current.stops.map(p=>p.id));work.change(()=>{if(keep)pending.value!.stops.push(...current.stops);data.value!.route.days=data.value!.route.days.filter(g=>g.id!==current.id);});modal.value=null;void changeGroup(pending.value!.id);}
function reorder(id:string,to:number){const g=group.value!,from=g.stops.findIndex(p=>p.id===id);if(from<0||to<0||to>=g.stops.length)return;work.change(()=>{const [p]=g.stops.splice(from,1);g.stops.splice(to,0,p!);});}
let drag:{id:string;handle:HTMLElement;x:number;y:number;moved:boolean}|undefined;
function dragStart(e:PointerEvent,id:string){if(e.button!==0)return;const handle=e.currentTarget as HTMLElement;handle.setPointerCapture(e.pointerId);drag={id,handle,x:e.clientX,y:e.clientY,moved:false};}
function dragMove(e:PointerEvent){if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6)drag.moved=true;if(drag.moved){const list=pointsScroll.value,box=list?.getBoundingClientRect();if(list&&box){if(e.clientY<box.top+40)list.scrollTop-=14;else if(e.clientY>box.bottom-40)list.scrollTop+=14;}}}
function dragEnd(e:PointerEvent){const previous=drag;drag=undefined;if(!previous)return;if(previous.moved){const target=document.elementFromPoint(e.clientX,e.clientY)?.closest<HTMLElement>('[data-point]');if(target?.dataset.point&&target.dataset.point!==previous.id)reorder(previous.id,group.value!.stops.findIndex(p=>p.id===target.dataset.point));}else{selectedPoint.value=previous.id;detail.value={time:active.value?.time||'',note:active.value?.note||'',stay:data.value!.preferences.stayNotes[previous.id]||''};open('point');}}
function startRecord(){recordSelected.value=[];recordExtras.value=[];recordDate.value=new Date().toLocaleDateString('sv-SE');recordKey=mutationId();open('record');}
async function record(){modalBusy.value=true;modalError.value='';try{if(!await work.flush())throw Error('请先处理未保存的修改，再确认到访。');const selectedPoints=recordPoints.value.filter(p=>recordSelected.value.includes(p.id));await api('/journeys/'+journeyId+'/workspace/visits','POST',{journeyVersion:data.value!.journey.version,routeVersion:data.value!.route.version,visitedOn:recordDate.value,selected:selectedPoints.map(p=>{const {id,...stop}=work.stopInput(p);return{...(allPoints.value.some(s=>s.id===id)?{sourceId:id}:{}),stop,place:data.value!.preferences.places[id]||recordExtras.value.find(x=>x.id===id)?.place}}),clientMutationId:recordKey});modal.value=null;await work.load(journeyId,false);notify('已确认实际到访，其余计划保持不变');}catch(e){modalError.value=errorText(e);}finally{modalBusy.value=false;}}
async function deleteJourney(){modalBusy.value=true;modalError.value='';try{if(!await work.flush())throw Error('请先处理未保存的修改，再删除旅程。');const j=data.value!.journey,versions:Record<string,number>={[data.value!.route.id]:data.value!.route.version};if(j.actualRouteId){const actual=await api<RouteSnapshot>('/routes/'+j.actualRouteId);versions[actual.id]=actual.version;}await api('/journeys/'+journeyId,'DELETE',{journeyVersion:j.version,routeVersions:versions,acknowledge:true,clientMutationId:deleteKey});modal.value=null;await router.replace('/journeys');}catch(e){modalError.value=errorText(e);}finally{modalBusy.value=false;}}
function applyDates(){work.change(()=>scheduled.value.forEach((d,i)=>d.date=nextDate(dateInput.value||null,i)));modal.value=null;}
function setTransport(mode:TravelMode){work.change(()=>{if(transportTarget.value)arrivalModes.value[transportTarget.value]=mode;else{data.value!.preferences.defaultModes[group.value!.id]=mode;for(const p of group.value!.stops)arrivalModes.value[p.id]=mode;}});modal.value=null;}
function closeSearch(){search.value=false;if(searchRecord.value)open('record');locating.value=null;}
async function reload(){if(!confirm('放弃当前本机草稿并读取服务器最新版本？可先下载草稿。'))return;await work.load(journeyId,false);groupId.value=data.value?.route.days[0]?.id||'';}
onMounted(async()=>{void loadAtlasCatalog().then(c=>cities.value=c.cities).catch(()=>{});if(journeyId){await work.load(journeyId);if(data.value){groupId.value=(pending.value?.stops.length ? pending.value : scheduled.value[0] || pending.value)!.id;try{const c=JSON.parse(sessionStorage.getItem(contextKey)||'null');if(c){if(data.value.route.days.some(d=>d.id===c.group))groupId.value=c.group;view.value=c.view==='map'?'map':'list';if(view.value==='map')mapSeen.value=true;selectedPoint.value=c.active;for(const [key,value]of c.scrolls||[])scrolls.set(key,value);}}catch{}await nextTick();if(pointsScroll.value)pointsScroll.value.scrollTop=scrolls.get(groupId.value)||0;}}else{await loadList();if(page.path.endsWith('/new'))newJourney();}});
onBeforeUnmount(()=>{wideScreen.removeEventListener('change',resizeScreen);remember();clearTimeout(noticeTimer);listGeneration++;});
onBeforeRouteLeave(async()=>{if(work.dirty.value&&!await work.flush())return confirm('服务器尚未保存成功，本机草稿会保留，仍要离开？');return true;});
</script>
<template><section class="planner-app journey-workspace-page" :class="{'is-workspace':!!journeyId}">
<p v-if="loading" class="pl-starting" role="status">正在打开这次旅程…</p>
<template v-if="!journeyId"><div class="pl-list"><header class="pl-list-head"><div><p class="pl-eyebrow">A JOURNEY OF YOUR OWN</p><h2>{{ filter==='archived'?'已归档的旅程':'旅程' }}</h2></div><div class="pl-list-actions"><button class="pl-icon-button" aria-label="旅程列表选项" @click="open('listMore')"><AtlasIcon name="more"/></button><button class="pl-icon-button pl-create" aria-label="新建旅程" @click="newJourney"><AtlasIcon name="plus"/></button></div></header><div class="pl-list-tabs"><button :aria-pressed="filter==='planning'" @click="setFilter('planning')">计划中</button><button :aria-pressed="filter==='completed'" @click="setFilter('completed')">已完成</button></div><p v-if="listBusy" class="pl-panel-copy">正在读取旅程…</p><p v-if="listError" class="pl-error">{{ listError }}<button class="pl-text-button" @click="loadList()">重试</button></p><div class="pl-journey-list"><button v-for="j in items" :key="j.id" class="pl-journey-card" @click="router.push('/journeys/'+j.id)"><span v-if="j.coverUrl" class="pl-cover"><img :src="j.coverUrl" :alt="j.title+'的照片'"></span><span v-else class="pl-empty-cover"><AtlasIcon name="route"/></span><span class="pl-card-body"><span class="pl-card-date">{{ j.dayCount ? j.dayCount+' 天' : '日期与天数待定' }}</span><h3>{{ j.title }}</h3><p>{{ j.destinations.join(' · ') || '先留下想去的地方' }}</p></span><AtlasIcon name="chevronRight"/></button></div><div v-if="!items.length&&!listBusy&&!listError" class="pl-empty"><AtlasIcon name="compass"/><h3>下一程，慢慢开始</h3><p>轻点右上角加号，先记一个想去的地方。</p></div><button v-if="cursor" class="pl-secondary" :disabled="listBusy" @click="loadList(true)">加载更多</button></div></template>
<template v-else-if="data && group"><section class="pl-workspace" :data-view="view"><header class="pl-topbar"><button class="pl-icon-button" aria-label="返回旅程列表" @click="router.push('/journeys')"><AtlasIcon name="back"/></button><button class="pl-title-button" aria-label="修改旅程名称" @click="nameDraft=data.journey.title;open('rename')"><strong>{{ data.journey.title }}</strong><small>{{ data.journey.status==='completed'?'已完成':data.journey.status==='archived'?'已归档':'计划中' }}</small></button><button class="pl-icon-button" aria-label="旅程更多选项" @click="open('more')"><AtlasIcon name="more"/></button></header><div class="pl-meta-row"><button class="pl-date-button" @click="dateInput=scheduled[0]?.date||'';open('dates')"><AtlasIcon name="calendar"/>{{ scheduled[0]?.date?.replaceAll('-','.')||'日期未定' }}</button><div class="pl-save-status" :class="{'is-error':state==='error'||state==='conflict'}" aria-live="polite">{{ saving?'正在保存…':state==='error'?'尚未保存到服务器':state==='conflict'?'版本有冲突':state==='dirty'?'等待保存…':statusNotice||'已保存到服务器' }}<button v-if="state==='error'" class="pl-text-button" @click="work.save">重试</button></div></div>
<div v-if="error" class="journey-error" role="alert">{{ error }}<template v-if="state==='conflict'"><button class="pl-text-button" @click="work.exportDraft">下载草稿</button><button class="pl-text-button" @click="reload">读取最新版本</button></template></div>
<nav class="pl-group-rail" aria-label="旅程安排分组"><button v-for="day in data.route.days" :key="day.id" class="pl-group-button" :aria-selected="group.id===day.id" :data-group="day.id" @click="changeGroup(day.id)"><strong>{{ groupName(day) }}</strong><small>{{ day.stops.length }} 个地点</small></button><button class="pl-add-day" aria-label="增加一天" @click="addDay"><AtlasIcon name="plus"/>增加一天</button></nav>
<div class="pl-workspace-content"><div class="pl-body-toolbar"><h2>{{ groupName(group) }}</h2><div class="pl-body-tools"><button class="pl-text-button" :disabled="!allPoints.length" @click="batch ? selectAll() : batch=true">{{ batch?'全选':'整理' }}</button><div class="pl-view-switch" role="group" aria-label="安排视图"><button :aria-pressed="view==='list'" @click="setView('list')"><AtlasIcon name="list"/>清单</button><button :aria-pressed="view==='map'" @click="setView('map')"><AtlasIcon name="map"/>地图</button></div><button class="pl-icon-button" aria-label="当前分组选项" @click="open('group')"><AtlasIcon name="more"/></button></div></div><div class="pl-split"><section class="pl-list-pane"><div ref="pointsScroll" class="pl-points-scroll" @scroll.passive="remember"><template v-for="(point,index) in group.stops" :key="point.id"><div v-if="index>0&&!group.unscheduled&&!batch" class="pl-transport-row"><button class="pl-text-button" :aria-label="'设置到'+point.label+'的交通'" @click="transportTarget=point.id;open('transport')">{{ modeLabels[arrivalModes[point.id]||'unknown'] }}<AtlasIcon name="chevronDown"/></button></div><article class="pl-stop-row" :class="{selected:selectedPoint===point.id}" :data-point="point.id"><label v-if="batch" class="pl-selection-check"><input type="checkbox" :checked="selected.includes(point.id)" :aria-label="'选择'+point.label" @change="toggleSelected(point.id)"></label><button class="pl-stop-open" :aria-label="'查看地点：'+point.label" @click="batch ? toggleSelected(point.id) : showPoint(point.id)"><span class="pl-stop-number">{{ String(index+1).padStart(2,'0') }}</span><span class="pl-stop-main"><strong>{{ point.label }}</strong><small>{{ point.region||'地区待补充' }}</small><p v-if="point.note" class="pl-stop-note">{{ point.note }}</p><span class="pl-stop-meta"><span v-if="!point.location" class="pl-stop-label">位置待补</span><span v-if="confirmed.includes(point.id)" class="pl-stop-label is-visited">已确认到访</span><span v-if="point.time" class="pl-stop-label">预约 {{ point.time }}</span></span></span></button><button v-if="!batch" class="pl-drag-handle" :aria-label="'拖动排序'+point.label+'，也可点击调整'" @pointerdown="dragStart($event,point.id)" @pointermove="dragMove" @pointerup="dragEnd" @pointercancel="drag=undefined"><AtlasIcon name="grip"/></button></article></template><div v-if="!group.stops.length" class="pl-day-empty"><p>{{ group.unscheduled?'先记下，想去的地方。':'这一天，留一点空白。' }}</p><small>{{ group.unscheduled?'现在不用定日期，也不用决定顺序。':'从待安排移过来，或继续搜索添加。' }}</small></div><button class="pl-add-place" @click="openSearch()"><AtlasIcon name="plus"/>添加地点</button></div></section><section class="pl-map-pane"><div class="journey-map-frame"><JourneyMap v-if="mapSeen || desktop" :key="group.id" :points="group.stops" :selected="selectedPoint" :pending="group.unscheduled" :city="searchCity" @select="selectedPoint=$event"/></div><div class="pl-map-selection"><div v-if="active" class="od-field"><strong>{{ active.label }}</strong><small>{{ active.region }}</small></div><small v-else>轻点地点，查看和补充安排。</small><button v-if="active" class="pl-text-button" @click="showPoint(active.id)">查看地点</button><button v-else class="pl-text-button" @click="openSearch()">添加地点</button></div></section></div></div>
<footer v-if="batch" class="pl-batch-bar"><span>已选 {{ selected.length }}</span><button class="pl-text-button" @click="batch=false;selected=[]">取消</button><button class="pl-text-button" :disabled="!selected.length" @click="removePoints(selected)">移除</button><button class="pl-primary" :disabled="!selected.length" @click="open('move')">移到…</button></footer>
<div v-if="undoItems.length" class="journey-undo-bar" role="status"><span>已移除 {{ undoItems.length }} 个地点</span><button class="pl-text-button" @click="undo">撤销</button><button class="pl-icon-button" aria-label="关闭撤销提示" @click="undoItems=[]"><AtlasIcon name="close"/></button></div>
</section></template>
<p v-else-if="error" class="journey-error" role="alert">{{ error }}<button class="pl-text-button" @click="work.load(journeyId)">重试</button></p>
<JourneyPlaceSearch v-if="search" :city="searchCity" :target="searchRecord?'补记 · 临时到访地点':groupName(data?.route.days.find(g=>g.id===searchTarget))" :added="addedIds" :count="searchCount" :locating="!!locating" @close="closeSearch" @toggle="usePlace($event)" @update="usePlace($event,true)"/>
<ModalSheet v-else-if="modal" :title="({create:'从一个念头开始',more:'这段旅程',rename:'这次旅行叫什么？',dates:'什么时候出发？',point:active?.label||'地点详情',move:'移到哪里？',group:groupName(group)+' · 选项',deleteDay:'删除这一天？',transport:'这段怎么走？',record:'补记这次出行',delete:'删除这段旅程？',listMore:'旅程列表'})[modal]" :busy="modalBusy" @close="modal=null">
<p v-if="modalError" class="pl-error" role="alert">{{ modalError }}</p>
<template v-if="modal==='create'"><label class="pl-field"><span>想去哪里，或给这次旅行起个名字</span><input v-model="input" aria-label="想去哪里，或给这次旅行起个名字" maxlength="80" placeholder="武汉，或国庆慢慢走" @input="cityChoice=''" @keydown.enter.prevent="create"></label><button v-for="city in cities.filter(c=>input.trim()&&c.name.includes(input.trim())).slice(0,6)" :key="city.code" class="pl-option" @click="cityChoice=city.name;input=city.name.replace(/市$/,'')+'之行'"><span>{{ city.name }}</span><small>用这个城市开始</small></button><button class="pl-primary full" :disabled="!input.trim()||modalBusy" @click="create">开始安排</button></template>
<template v-else-if="modal==='listMore'"><button class="pl-option" @click="setFilter('archived');modal=null">查看已归档</button></template>
<template v-else-if="modal==='more'"><button class="pl-option" @click="nameDraft=data!.journey.title;open('rename')">修改名称</button><button class="pl-option" @click="dateInput=scheduled[0]?.date||'';open('dates')">设置日期</button><button class="pl-option" @click="startRecord">补记这次出行</button><button class="pl-option" @click="work.change(()=>data!.journey.status=data!.journey.status==='completed'?'planning':'completed');modal=null">{{ data!.journey.status==='completed'?'改为计划中':'标记为已完成' }}</button><button class="pl-option" @click="work.change(()=>data!.journey.status=data!.journey.status==='archived'?'planning':'archived');modal=null">{{ data!.journey.status==='archived'?'取消归档':'归档旅程' }}</button><button class="pl-option" @click="modal=null;router.push('/journeys/'+journeyId+'/map')">路线与 GPX 工具</button><button class="pl-option" @click="modal=null;router.push('/journeys/'+journeyId+'/actual')">查看实际记录</button><button class="pl-option" @click="modal=null;router.push('/journeys/'+journeyId+'/share')">分享这次旅程</button><button class="pl-option" @click="modal=null;router.push('/journeys/'+journeyId+'/edit')">详细安排与图文</button><button class="pl-option pl-danger" @click="deleteKey=mutationId();open('delete')">删除旅程</button></template>
<template v-else-if="modal==='rename'"><label class="pl-field"><span>旅程名称</span><input v-model="nameDraft" maxlength="80" aria-label="旅程名称"></label><button class="pl-primary" :disabled="!nameDraft.trim()" @click="work.change(()=>data!.journey.title=nameDraft.trim());modal=null">完成</button></template>
<template v-else-if="modal==='dates'"><label class="pl-field"><span>出发日期（选填）</span><input v-model="dateInput" type="date" aria-label="出发日期" min="1900-01-01" max="2200-11-30"></label><p class="pl-panel-copy">已有天数从这一天顺延。</p><div class="journey-actions"><button class="pl-secondary" @click="dateInput='';applyDates()">日期未定</button><button class="pl-primary" @click="applyDates">完成</button></div></template>
<template v-else-if="modal==='point'&&active"><p class="pl-panel-copy">{{ active.region||'位置待补' }}</p><label class="pl-field"><span>预约时间（选填）</span><input v-model="detail.time" @change="savePoint(false)" type="time" aria-label="预约时间"></label><label class="pl-field"><span>短备注（选填）</span><textarea v-model="detail.note" @input="savePoint(false)" maxlength="10000" aria-label="地点短备注"></textarea></label><label class="pl-field"><span>住宿补充（选填）</span><input v-model="detail.stay" @input="savePoint(false)" maxlength="300" aria-label="住宿补充"></label><details class="pl-point-actions"><summary>整理这个地点</summary><button class="pl-option" @click="selected=[active!.id];open('move')">移到某天</button><div class="journey-actions"><button class="pl-secondary" @click="reorder(active!.id,group!.stops.findIndex(p=>p.id===active!.id)-1)">向上移动</button><button class="pl-secondary" @click="reorder(active!.id,group!.stops.findIndex(p=>p.id===active!.id)+1)">向下移动</button></div><button class="pl-option" @click="openSearch(false,active!.id)">搜索并补充位置</button><button class="pl-option pl-danger" @click="removePoints([active!.id])">移除地点</button></details><button class="pl-primary full" @click="savePoint()">完成</button></template>
<template v-else-if="modal==='move'"><button v-for="day in data!.route.days" :key="day.id" class="pl-option" :aria-label="'移到'+groupName(day)" @click="moveTo(day.id)">{{ groupName(day) }}<small>{{ day.stops.length }} 个地点</small></button></template>
<template v-else-if="modal==='group'"><button class="pl-option" @click="batch=true;modal=null">选择多个地点</button><template v-if="!group?.unscheduled"><button class="pl-option" @click="transportTarget=null;open('transport')">当天默认交通</button><button class="pl-option pl-danger" @click="open('deleteDay')">删除这一天</button></template></template>
<template v-else-if="modal==='deleteDay'"><p class="pl-panel-copy">这一天有 {{ group?.stops.length }} 个地点，选择怎么处理。</p><button class="pl-option" @click="deleteDay(true)">地点移回待安排</button><button class="pl-option pl-danger" @click="deleteDay(false)">一并移除当天地点</button></template>
<template v-else-if="modal==='transport'"><button v-for="mode in (['unknown','walk','hike','transit','drive','bike','rail','flight','boat','other'] as TravelMode[])" :key="mode" class="pl-option" @click="setTransport(mode)">{{ modeLabels[mode] }}</button></template>
<template v-else-if="modal==='record'"><p class="pl-panel-copy">只勾选真正去过的地方，其余计划保持不变。已经确认的到访会保留。</p><label class="pl-field"><span>实际到访日期</span><input v-model="recordDate" type="date" aria-label="实际到访日期"></label><label v-for="p in recordPoints" :key="p.id" class="journey-record-option"><input v-if="confirmed.includes(p.id)" type="checkbox" checked disabled :aria-label="p.label+'此前已确认到访'"><input v-else v-model="recordSelected" type="checkbox" :value="p.id" :aria-label="'确认到访'+p.label"><span>{{ p.label }}<small>{{ confirmed.includes(p.id)?'此前已确认到访':p.region }}</small></span></label><button class="pl-text-button" @click="openSearch(true)">添加临时到访地点</button><p class="pl-panel-copy">照片可稍后到回忆中添加，无需写日记。</p><button class="pl-primary full" :disabled="!recordDate||!recordSelected.length||modalBusy" @click="record">确认 {{ recordSelected.length }} 处到访</button></template>
<template v-else-if="modal==='delete'"><p class="pl-panel-copy">{{ data?.journey.title }}</p><ul class="journey-delete-effects"><li>删除这次旅程的计划、实际安排和 {{ data?.visits.length }} 条到访补记。</li><li>旅程分享链接失效。</li><li>独立相册照片和原有日记保留，原日记关联地点将显示为已移除。</li></ul><button class="pl-primary full" :disabled="modalBusy||saving" @click="deleteJourney">{{ modalBusy?'正在删除…':'确认删除旅程' }}</button></template>
</ModalSheet></section></template>
